#!/usr/bin/env python3
import re

# Read the extracted content
with open('/tmp/all_extracted.txt') as f:
    content = f.read()

# Extract key markers
lines = content.split('\n')

# Find all file boundaries
file_boundaries = []
for i, line in enumerate(lines):
    if '===== FILE' in line:
        file_boundaries.append((i, line))

print(f"Total lines: {len(lines)}")
print(f"File boundaries: {len(file_boundaries)}")
print("\nFirst 5 and last 5 files:")
for i, line in file_boundaries[:5]:
    print(f"  {i:5d}: {line}")
print("  ...")
for i, line in file_boundaries[-5:]:
    print(f"  {i:5d}: {line}")

# Extract user messages with key patterns
print("\n=== KEY USER MESSAGES ===")
user_messages = []
for i, line in enumerate(lines):
    if ' user: ' in line and any(keyword in line for keyword in ['фабл', 'сол', 'что', 'какой', 'работ', 'проблем', 'несколько']):
        user_messages.append((i, line))

for i, line in user_messages[:15]:
    print(f"{i:5d}: {line[:200]}")

# Extract assistant messages mentioning specific work
print("\n=== KEY ACCOMPLISHMENTS (grep for deploy/push/merge/commit) ===")
accomplishments = []
for i, line in enumerate(lines):
    if ' assistant: ' in line and any(kw in line.lower() for kw in ['deployed', 'pushed', 'merged', 'completed', 'done', 'commit', 'напис', 'запустил', 'готов']):
        accomplishments.append((i, line))

for i, line in accomplishments[:15]:
    print(f"{i:5d}: {line[:200]}")

# Look for codex/Sol sessions
print("\n=== CODEX SESSION MARKERS (Sol) ===")
codex_lines = []
for i, line in enumerate(lines):
    if 'CODEX SESSION' in line or 'codex-' in line:
        codex_lines.append((i, line))

for i, line in codex_lines[:10]:
    print(f"{i:5d}: {line[:200]}")

# Look for Fable mentions
print("\n=== FABLE MENTIONS ===")
fable_lines = []
for i, line in enumerate(lines):
    if 'Fable' in line or 'fable' in line:
        fable_lines.append((i, line))

for i, line in fable_lines[:15]:
    print(f"{i:5d}: {line[:150]}")

EOF
